/* Œconomia — Entraînement : thème « Marché et prix » (trois niveaux, douze exercices par niveau).
   Les autres thèmes sont annoncés et seront ajoutés dans des fichiers semblables. */
(function () {
  const X = OEC.exo, { rnd, pick, fmt, marche } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");
  const lin = (a, b, v = "P") => `${a} − ${b === 1 ? "" : b}${v}`;
  const linp = (c, d, v = "P") => (c >= 0 ? `${c} + ${d === 1 ? "" : d}${v}` : `${d === 1 ? "" : d}${v} − ${-c}`);

  X.theme({ id: "marche", nom: "Marché et prix",
    intro: "Comment se forment les prix ? Ces exercices vous entraînent à raisonner avec l’offre et la demande, à calculer des variations, des élasticités et des surplus, et à analyser l’effet des taxes, des prix plafonds et du monopole.",
    notions: ["offre-demande", "elasticite", "surplus", "cout-opportunite", "utilite-marginale", "concurrence-imparfaite", "equilibre-nash", "valeur-usage"] });
  ["Monnaie et inflation", "Croissance et PIB", "Emploi et chômage", "Commerce international", "Inégalités et répartition", "État et biens publics", "Finance"].forEach((n, i) =>
    X.theme({ id: "bientot" + i, nom: n, bientot: true, intro: "", notions: [] }));

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "m1-loi-demande", theme: "marche", niveau: 1, type: "qcm", notion: "offre-demande",
    titre: "La loi de la demande", competence: "Connaître le lien entre le prix d’un bien et la quantité demandée.",
    enonce: P("Le prix d’un abonnement de streaming passe de 12 à 16 francs par mois, toutes choses égales par ailleurs. Que prévoit la loi de la demande ?"),
    options: ["Le nombre d’abonnés augmente, car un prix élevé signale la qualité.", "La quantité demandée diminue.", "La quantité demandée reste identique, car les clients sont fidèles.", "La courbe de demande se déplace vers la droite."], c: 1, pourquoi: ["Le signal de qualité joue pour quelques produits de luxe, mais la loi de la demande décrit le cas général : à goûts inchangés, un prix plus élevé fait renoncer une partie des clients.", null, "Des clients fidèles réagissent peu, mais rarement pas du tout : certains résilient ou partagent un compte. La quantité demandée baisse, même faiblement.", "La courbe se déplace quand autre chose que le prix change (revenus, goûts, prix des concurrents). Une hausse du prix du bien lui-même fait glisser le long de la courbe."],
    explication: P("Quand le prix d’un bien augmente, et que tout le reste est inchangé (revenus, goûts, prix des autres biens), la <b>quantité demandée diminue</b> : certains clients renoncent ou se tournent vers un concurrent. On se déplace <i>le long</i> de la courbe de demande ; la courbe elle-même ne bouge pas.") },

  { id: "m1-variation", theme: "marche", niveau: 1, type: "calcul", notion: "offre-demande",
    titre: "Calculer une variation de prix", competence: "Calculer un taux de variation en pourcentage.",
    gen: () => { const p0 = rnd(25, 60) / 10; const g = pick([-15, -12, -10, -8, -5, 5, 6, 8, 10, 12, 15, 20, 25]); const p1 = Math.round(p0 * (1 + g / 100) * 20) / 20; return { p0, p1 }; },
    enonce: (p) => P(`Le prix d’un café dans une gare passe de <b>${fmt(p.p0)} fr.</b> à <b>${fmt(p.p1)} fr.</b>`, "De combien de pourcentage le prix a-t-il varié ? Arrondissez à une décimale ; indiquez un signe moins s’il s’agit d’une baisse."),
    champs: [{ label: "Variation", unite: "%", tol: 0.06 }],
    reponses: (p) => [X.arr(((p.p1 - p.p0) / p.p0) * 100, 1)],
    indice: "Taux de variation = (valeur d’arrivée − valeur de départ) ÷ valeur de départ × 100.",
    correction: (p) => { const v = ((p.p1 - p.p0) / p.p0) * 100; return P(`Taux de variation = (${fmt(p.p1)} − ${fmt(p.p0)}) ÷ ${fmt(p.p0)} × 100`, `= ${fmt(p.p1 - p.p0)} ÷ ${fmt(p.p0)} × 100 ≈ <b>${fmt(X.arr(v, 1), 1)} %</b>.`, v < 0 ? "Le résultat est négatif : c’est une baisse de prix." : "Le résultat est positif : c’est une hausse de prix."); } },

  { id: "m1-deplacement", theme: "marche", niveau: 1, type: "graphique", notion: "offre-demande",
    titre: "Lire un déplacement de courbe", competence: "Distinguer un déplacement de la demande d’un mouvement le long de la courbe.",
    enonce: P("Sur le marché des glaces en Suisse, on observe le déplacement représenté ci-dessous : la courbe de demande D passe en D′.", "Quel événement peut expliquer ce déplacement ?"),
    fig: () => marche({ shift: "demande+", caption: "La demande passe de D à D′ ; l’équilibre passe de E à E′." }),
    options: ["Le prix des glaces a baissé, ce qui pousse les consommateurs à en acheter plus.","Une vague de chaleur rend les glaces plus désirables à chaque prix.","Le coût du lait, utilisé pour fabriquer les glaces, a augmenté.","De nouveaux fabricants de glaces se sont installés sur le marché."], c: 1, pourquoi: ["Une baisse du prix fait glisser le long de la courbe de demande ; elle ne la déplace pas.", null, "Le coût du lait concerne les producteurs : il déplace la courbe d’offre, pas celle de la demande.", "De nouveaux fabricants augmentent l’offre : c’est la courbe d’offre qui se déplace."],
    explication: P("La courbe de demande se déplace vers la droite quand, <b>à chaque prix</b>, les consommateurs veulent davantage du bien : changement de goûts, de météo, hausse des revenus, hausse du prix d’un substitut. La baisse du prix ne déplace pas la courbe : elle fait glisser le long de celle-ci. Le coût du lait et l’arrivée de nouveaux fabricants touchent l’<i>offre</i>.", "Résultat : au nouvel équilibre E′, le prix <b>et</b> la quantité échangée augmentent.") },

  { id: "m1-vf-marche", theme: "marche", niveau: 1, type: "vf", notion: "offre-demande",
    titre: "Offre, demande et équilibre", competence: "Utiliser correctement le vocabulaire de base du marché.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Au prix d’équilibre, la quantité offerte est égale à la quantité demandée.", true, "C’est la définition de l’équilibre : il n’y a ni pénurie ni excédent."],
      ["Une hausse du prix du beurre peut faire augmenter la demande de margarine.", true, "Le beurre et la margarine sont des <b>substituts</b> : quand l’un devient plus cher, une partie des acheteurs se reporte sur l’autre."],
      ["Une amélioration technique qui réduit les coûts de production déplace la courbe d’offre vers la gauche.", false, "Elle rend la production moins coûteuse : à chaque prix, les entreprises veulent produire davantage. L’offre se déplace vers la <b>droite</b>."],
      ["Si le prix est supérieur au prix d’équilibre, il y a une pénurie.", false, "Au-dessus de l’équilibre, les vendeurs offrent plus que ce que les acheteurs demandent : il y a un <b>excédent</b>, qui pousse le prix à la baisse."]
    ] },

  { id: "m1-cout-opp", theme: "marche", niveau: 1, type: "qcm", notion: "cout-opportunite",
    titre: "Le coût d’opportunité", competence: "Identifier ce à quoi on renonce quand on fait un choix.",
    enonce: P("Léa, apprentie, peut travailler le samedi dans un magasin pour 120 francs, ou partir faire une randonnée avec des amis. Le trajet en train coûte 30 francs. Elle choisit la randonnée.", "Combien cette randonnée lui coûte-t-elle en tout, si l’on compte ce qu’elle dépense et ce à quoi elle renonce ? Ce total est son coût d’opportunité."),
    options: ["30 francs, le prix du billet de train.", "120 francs, le salaire auquel elle renonce.", "150 francs, le billet plus le salaire perdu.", "Rien, puisqu’elle a choisi ce qu’elle préférait."], c: 2, pourquoi: ["Le billet n’est qu’une partie du coût : il faut ajouter le salaire de 120 francs auquel Léa renonce.", "Le salaire perdu compte, mais le billet aussi : la randonnée coûte les deux.", null, "Choisir ce qu’on préfère ne rend pas le choix gratuit : on renonce quand même à la meilleure autre option."],
    explication: P("Le coût d’opportunité d’un choix réunit <b>tout ce à quoi l’on renonce</b> pour le faire, c’est-à-dire l’argent dépensé et la valeur de la meilleure autre option. En partant en randonnée, Léa dépense 30 francs <i>et</i> renonce à gagner 120 francs : son choix lui coûte en réalité 150 francs. Elle a raison de partir si la randonnée vaut au moins cela à ses yeux.") },

  { id: "m1-calc-opp", theme: "marche", niveau: 1, type: "calcul", notion: "cout-opportunite",
    titre: "Chiffrer un coût d’opportunité", competence: "Chiffrer le coût complet d’un choix.",
    gen: () => ({ billet: rnd(5, 18) * 5, h: rnd(3, 6), w: rnd(20, 32) }),
    enonce: (p) => P(`Samir hésite à aller à un concert le jeudi soir. Le billet coûte <b>${p.billet} francs</b>. Pour y aller, il doit renoncer à un service de <b>${p.h} heures</b> dans un restaurant, payé <b>${p.w} francs de l’heure</b>.`, "Quel est le coût d’opportunité total du concert ?"),
    champs: [{ label: "Coût d’opportunité", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [p.billet + p.h * p.w],
    indice: "Le concert lui coûte ce qu’il paie, mais aussi ce qu’il ne gagne pas ce soir-là. Chiffrez d’abord ce revenu perdu.",
    correction: (p) => P(`Revenu auquel Samir renonce : ${p.h} × ${p.w} = ${p.h * p.w} francs.`, `Coût d’opportunité = billet + revenu perdu = ${p.billet} + ${p.h * p.w} = <b>${p.billet + p.h * p.w} francs</b>.`, "Le prix affiché n’est qu’une partie du coût réel d’un choix.") },

  { id: "m1-eau-diamant", theme: "marche", niveau: 1, type: "qcm", notion: "utilite-marginale",
    titre: "Le paradoxe de l’eau et du diamant", competence: "Expliquer pourquoi un bien très utile peut être bon marché.",
    enonce: P("L’eau est indispensable à la vie, mais très bon marché ; un diamant est presque inutile, mais très cher. Comment les économistes marginalistes expliquent-ils ce paradoxe, soulevé par Adam Smith ?"),
    options: ["Le diamant demande beaucoup plus de travail de production que l’eau.", "Les prix sont fixés arbitrairement par les vendeurs, sans lien avec les besoins.", "Le prix dépend de l’utilité de la dernière unité : l’eau abonde, le diamant est rare.", "L’eau est un bien public, alors que le diamant est un bien privé."], c: 2, pourquoi: ["C’est l’explication des classiques par le travail. Les marginalistes la jugent insuffisante : un objet qui a demandé beaucoup de travail mais dont personne ne veut ne se vend pas cher.", "Les vendeurs ne fixent pas les prix à leur guise : ils dépendent de ce que les acheteurs sont prêts à payer, donc de la rareté.", null, "L’eau n’est pas un bien public au sens économique : on peut faire payer chaque litre, et un litre bu n’est plus disponible pour un autre."],
    explication: P("Ce qui fixe le prix n’est pas l’utilité <i>totale</i> d’un bien, mais son <b>utilité marginale</b>, celle de la dernière unité. L’eau est si abondante que son dernier litre ne sert qu’à des usages peu importants ; le diamant est si rare que la dernière pierre reste très désirée. Le travail joue aussi un rôle à long terme, par le coût de production, mais il n’explique pas tout.") },

  { id: "m1-tableau", theme: "marche", niveau: 1, type: "document", notion: "offre-demande",
    titre: "Lire un tableau d’offre et de demande", competence: "Lire un tableau d’offre et de demande.",
    enonce: P("Voici l’offre et la demande de paniers de légumes bio sur un marché hebdomadaire :") +
      `<table><thead><tr><th>Prix (fr.)</th><th>Quantité demandée</th><th>Quantité offerte</th></tr></thead><tbody>
      <tr><td>15</td><td>140</td><td>40</td></tr><tr><td>20</td><td>110</td><td>70</td></tr><tr><td>25</td><td>90</td><td>90</td></tr><tr><td>30</td><td>70</td><td>115</td></tr><tr><td>35</td><td>50</td><td>140</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Le prix d’équilibre est de 25 francs. Que se passe-t-il si le vendeur fixe le prix à 30 francs ?"),
    options: ["Il y a une pénurie de 45 paniers.", "Il reste 45 paniers invendus.", "Il reste 115 paniers invendus.", "Rien ne change, les 90 paniers se vendent."], c: 1, pourquoi: ["À 30 francs, l’offre (115) dépasse la demande (70) : il y a des invendus, pas une pénurie. Une pénurie apparaît quand le prix est inférieur à l’équilibre.", null, "115 est la quantité offerte à 30 francs. Les invendus sont l’écart avec la quantité demandée, soit 115 − 70 = 45 paniers.", "À 30 francs, seuls 70 paniers trouvent preneur, et non 90. Le prix fixé n’est plus celui de l’équilibre."],
    explication: P("À <b>25 francs</b>, la quantité demandée (90) est égale à la quantité offerte (90) : c’est l’équilibre.", "À 30 francs, les producteurs apportent 115 paniers, mais les clients n’en veulent que 70 : il y a un <b>excédent</b> de 115 − 70 = 45 paniers invendus. Pour les écouler, les vendeurs devront baisser leur prix.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "m2-equilibre", theme: "marche", niveau: 2, type: "calcul", notion: "offre-demande",
    titre: "Calculer l’équilibre d’un marché", competence: "Résoudre un système d’offre et de demande linéaires.",
    gen: () => { const Ps = rnd(2, 6), Qs = rnd(30, 120), b = rnd(2, 6), d = rnd(2, 6); return { a: Qs + b * Ps, b, c: Qs - d * Ps, d, Ps, Qs }; },
    enonce: (p) => P("Sur le marché local des pommes, la demande et l’offre (en kilos par jour) sont données par :", `<b>Demande : Q<sub>d</sub> = ${lin(p.a, p.b)}</b> &nbsp;&nbsp; <b>Offre : Q<sub>o</sub> = ${linp(p.c, p.d)}</b>`, "où P est le prix en francs par kilo. Calculez le prix et la quantité d’équilibre."),
    champs: [{ label: "Prix d’équilibre", unite: "fr.", tol: 0.01 }, { label: "Quantité d’équilibre", unite: "kg", tol: 0.5 }],
    reponses: (p) => [p.Ps, p.Qs],
    indice: "À l’équilibre, Qd = Qo : écrivez l’égalité et isolez P, puis remplacez P dans l’une des deux équations.",
    correction: (p) => P(`À l’équilibre : ${lin(p.a, p.b)} = ${linp(p.c, p.d)}`, `On regroupe les P : ${p.a} − (${p.c}) = ${p.b}P + ${p.d}P, soit ${p.a - p.c} = ${p.b + p.d}P.`, `Donc P* = ${p.a - p.c} ÷ ${p.b + p.d} = <b>${p.Ps} francs</b>.`, `Quantité : Q* = ${p.a} − ${p.b} × ${p.Ps} = <b>${p.Qs} kg</b> (on vérifie avec l’offre : ${p.c} + ${p.d} × ${p.Ps} = ${p.Qs}).`) },

  { id: "m2-elasticite", theme: "marche", niveau: 2, type: "calcul", notion: "elasticite",
    titre: "Mesurer une élasticité-prix", competence: "Calculer l’élasticité-prix de la demande à partir de deux variations en pourcentage.",
    gen: () => { const dp = pick([5, 8, 10, 12, 15, 20]); const e = pick([0.3, 0.4, 0.5, 0.6, 0.8, 1.2, 1.5, 2]); return { dp, dq: -Math.round(dp * e * 10) / 10 }; },
    enonce: (p) => P(`Une compagnie de bus augmente ses tarifs de <b>${p.dp} %</b>. Le nombre de billets vendus varie de <b>${fmt(p.dq)} %</b>.`, "Calculez l’élasticité-prix de la demande, avec son signe, arrondie à deux décimales. Calculez ensuite la variation de la recette de la compagnie (prix × quantité), en pourcentage arrondi à une décimale et avec un signe moins pour une baisse. Dites enfin si la demande est élastique ou inélastique."),
    champs: [{ label: "Élasticité", unite: "", tol: 0.011 }, { label: "Variation de la recette", unite: "%", tol: 0.1 }, { label: "La demande est", choix: ["élastique", "inélastique"] }],
    reponses: (p) => [X.arr(p.dq / p.dp, 2), X.arr(p.dp + p.dq + p.dp * p.dq / 100, 1), Math.abs(p.dq / p.dp) > 1 ? 0 : 1],
    indice: "Élasticité-prix = variation en % de la quantité ÷ variation en % du prix. La recette est le produit du prix par la quantité : multipliez les deux coefficients multiplicateurs, 1 + variation ÷ 100.",
    correction: (p) => { const e = p.dq / p.dp, k = (1 + p.dp / 100) * (1 + p.dq / 100), v = (k - 1) * 100; return P(`Élasticité = ${fmt(p.dq)} % ÷ ${p.dp} % = <b>${fmt(e, 2)}</b>.`, `Recette = prix × quantité. Le prix est multiplié par ${fmt(1 + p.dp / 100, 2)} et la quantité par ${fmt(1 + p.dq / 100, 3)}, donc la recette par ${fmt(1 + p.dp / 100, 2)} × ${fmt(1 + p.dq / 100, 3)} = ${fmt(k, 4)}. Sa variation est de <b>${fmt(v, 1)} %</b>.`, Math.abs(e) < 1 ? `En valeur absolue, l’élasticité est inférieure à 1 : la demande est <b>inélastique</b>. La quantité réagit moins que le prix, donc la recette augmente.` : `En valeur absolue, l’élasticité est supérieure à 1 : la demande est <b>élastique</b>. La quantité réagit plus fortement que le prix, donc la recette diminue.`); } },

  { id: "m2-recette", theme: "marche", niveau: 2, type: "qcm", notion: "elasticite",
    titre: "Élasticité et recette", competence: "Prévoir l’effet d’une hausse de prix sur la recette.",
    enonce: P("L’élasticité-prix de la demande de cigarettes est estimée à environ −0,4. L’État augmente fortement les taxes, ce qui fait monter le prix du paquet de 10 %. Quel effet peut-on prévoir ?"),
    options: ["La consommation baisse d’environ 4 %, et les dépenses des fumeurs augmentent.","La consommation baisse d’environ 40 %, et les recettes fiscales s’effondrent.","La consommation ne change pas, car les fumeurs sont dépendants au tabac.","La consommation baisse de 10 %, autant que le prix du paquet."], c: 0, pourquoi: [null, "Une baisse de 40 % supposerait une élasticité de −4. Avec −0,4, la quantité baisse dix fois moins, et les recettes fiscales augmentent.", "La dépendance rend la demande peu élastique, mais pas nulle : une partie des fumeurs réduit sa consommation, surtout les jeunes.", "Une baisse de 10 % correspondrait à une élasticité de −1. Ici, la quantité réagit moins que le prix."],
    explication: P("Avec une élasticité de −0,4, une hausse de prix de 10 % réduit la quantité d’environ 0,4 × 10 = <b>4 %</b>. La demande est inélastique : le prix monte plus que la quantité ne baisse, donc la dépense totale augmente (environ 1,10 × 0,96 ≈ 1,056, soit +5,6 %).", "C’est pourquoi les taxes sur le tabac rapportent beaucoup à l’État. L’effet sur la santé existe, mais il est plus fort chez les jeunes, dont la demande est plus élastique.") },

  { id: "m2-taxe-graph", theme: "marche", niveau: 2, type: "graphique", notion: "surplus",
    titre: "L’effet d’une taxe sur le marché", competence: "Analyser graphiquement l’effet d’une taxe payée par les vendeurs.",
    enonce: P("L’État instaure une taxe de 1 franc par litre sur les boissons sucrées, payée par les producteurs. Sur le graphique, la courbe d’offre passe de O à « O + taxe ».", "Quel est l’effet de cette taxe sur le prix payé par les consommateurs et sur la quantité échangée ?"),
    fig: () => marche({ shift: "offre-", label: "O + taxe", caption: "La taxe augmente le coût de chaque litre vendu : l’offre se déplace vers le haut (vers la gauche)." }),
    options: ["Le prix payé par les consommateurs augmente exactement de 1 franc, et la quantité reste la même.", "Le prix payé monte de moins d’un franc, et la quantité échangée diminue.", "Le prix ne change pas : ce sont les producteurs qui paient toute la taxe.", "La quantité échangée augmente, car l’État dépense la recette de la taxe."], c: 1,
    pourquoi: ["Le prix ne monterait de toute la taxe que si la demande ne réagissait pas du tout au prix. Ici la demande est décroissante, une partie des acheteurs renonce et les vendeurs doivent absorber une part de la taxe.", null, "Les producteurs versent la taxe à l’État, mais ils en reportent une partie sur le prix de vente. Au nouvel équilibre E′, le prix payé par les consommateurs est plus élevé qu’en E.", "L’usage de la recette n’apparaît pas sur ce marché. La taxe renchérit chaque litre vendu, l’offre recule et la quantité échangée diminue de E à E′."],
    explication: P("Au nouvel équilibre E′, le prix payé par les consommateurs augmente et la quantité diminue. Mais la hausse de prix est en général <b>inférieure à la taxe</b> : une partie de la taxe est supportée par les consommateurs, l’autre par les producteurs, qui reçoivent moins par litre après avoir payé la taxe.", "Qui paie le plus dépend des élasticités : le côté du marché le moins capable de s’adapter (le plus inélastique) supporte la plus grande part. On appelle cela l’<b>incidence fiscale</b>.") },

  { id: "m2-surplus", theme: "marche", niveau: 2, type: "calcul", notion: "surplus",
    titre: "Calculer le surplus du consommateur", competence: "Calculer une surface sous la courbe de demande.",
    gen: () => { const B = pick([1, 2]); const Q = rnd(4, 12) * (B === 1 ? 2 : 1); const A = rnd(Math.ceil(B * Q / 1) + 4, B * Q + 20); return { A, B, Q, Pe: A - B * Q }; },
    enonce: (p) => P(`La demande de places pour une séance de cinéma en plein air est donnée par <b>P = ${p.A} − ${p.B === 1 ? "" : p.B}Q</b>, où P est le prix en francs et Q le nombre de places en centaines.`, `Le prix d’équilibre est de <b>${p.Pe} francs</b>, et ${p.Q} centaines de places sont vendues.`, "Calculez le surplus des consommateurs, en centaines de francs."),
    fig: "",
    champs: [{ label: "Surplus", unite: "centaines de fr.", tol: 0.5 }],
    reponses: (p) => [0.5 * (p.A - p.Pe) * p.Q],
    indice: "Le surplus est le triangle compris entre la courbe de demande et le prix payé : ½ × base × hauteur.",
    correction: (p) => P(`Le prix maximal que quelqu’un serait prêt à payer est ${p.A} francs (quand Q = 0).`, `Le surplus est le triangle de hauteur ${p.A} − ${p.Pe} = ${p.A - p.Pe} francs et de base ${p.Q} centaines de places.`, `Surplus = ½ × ${p.Q} × ${p.A - p.Pe} = <b>${fmt(0.5 * (p.A - p.Pe) * p.Q)} centaines de francs</b>, soit ${fmt(50 * (p.A - p.Pe) * p.Q)} francs.`, "C’est le gain total des spectateurs : la différence entre ce qu’ils étaient prêts à payer et ce qu’ils ont réellement payé.") },

  { id: "m2-vf-prix-reglementes", theme: "marche", niveau: 2, type: "vf", notion: "surplus",
    titre: "Prix plafonds et prix planchers", competence: "Prévoir les effets d’un prix fixé par l’État.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Un prix plafond fixé en dessous du prix d’équilibre provoque une pénurie.", true, "À ce prix bas, la quantité demandée dépasse la quantité offerte. Une partie des acheteurs ne trouve rien à acheter, d’où des files ou des listes d’attente."],
      ["Un prix plafond fixé au-dessus du prix d’équilibre n’a aucun effet.", true, "Le prix d’équilibre est déjà inférieur au plafond : la contrainte ne joue pas, on dit qu’elle n’est pas « contraignante »."],
      ["Un prix plancher fixé au-dessus de l’équilibre provoque un excédent.", true, "Au prix élevé, les vendeurs offrent plus que ce que les acheteurs demandent. C’est le cas des anciens prix garantis agricoles, qui ont créé des surplus de beurre ou de lait en Europe."],
      ["Un salaire minimum est un exemple de prix plafond appliqué au marché du travail.", false, "C’est un <b>prix plancher</b> sur le marché du travail : il interdit de payer moins qu’un certain montant. Ses effets sur l’emploi dépendent de son niveau et du fonctionnement du marché."]
    ] },

  { id: "m2-loyers-zurich", theme: "marche", niveau: 2, type: "redaction", notion: "offre-demande",
    titre: "Pourquoi les loyers sont-ils si élevés à Zurich et à Genève ?", competence: "Expliquer un fait économique avec l’offre et la demande.",
    enonce: P("Les loyers à Zurich et à Genève comptent parmi les plus élevés d’Europe, et le taux de logements vacants y est très faible, souvent inférieur à 1 %.", "<b>Consigne :</b> en vous appuyant sur l’offre et la demande, expliquez pourquoi les loyers y sont si élevés. Donnez au moins deux facteurs qui pèsent sur la demande et deux qui limitent l’offre, puis concluez. Longueur attendue, 12 à 18 lignes."),
    criteres: ["La réponse utilise explicitement l’offre et la demande (ou l’équilibre du marché).", "Elle cite au moins deux facteurs de demande : emplois attractifs, salaires élevés, croissance de la population, immigration, ménages plus petits…", "Elle cite au moins deux facteurs qui limitent l’offre : terrain rare, règles de construction et de protection du patrimoine, oppositions et recours, lenteur des procédures…", "Elle explique que l’offre ne suit pas la demande, d’où la hausse des prix et un faible taux de vacance.", "Elle conclut clairement, par exemple sur les pistes de solution ou les limites de l’explication."],
    corrige: P("Le loyer est le prix d’un service, le logement : il dépend de l’offre et de la demande. À Zurich et à Genève, la <b>demande</b> est très forte : ces villes concentrent des emplois bien payés dans la finance, la pharmacie, la technologie ou les organisations internationales, et attirent chaque année de nombreux habitants, suisses et étrangers. La taille moyenne des ménages diminue aussi, ce qui augmente le nombre de logements nécessaires.", "L’<b>offre</b>, elle, réagit lentement : le terrain est rare et cher, les règles de construction et de protection des sites limitent la densité, et les projets peuvent être retardés par des oppositions et des recours. Quand la demande progresse plus vite que l’offre, le prix d’équilibre monte, et la pénurie se traduit par un taux de vacance très bas.", "Pour faire baisser les loyers durablement, il faudrait surtout augmenter l’offre, par la densification ou la construction de logements d’utilité publique ; plafonner les loyers sans construire risquerait d’aggraver la pénurie.", "À noter : en Suisse, le droit du bail encadre les hausses de loyer pour les locataires en place. C’est surtout le loyer proposé aux nouveaux locataires qui reflète la tension entre l’offre et la demande, d’où l’écart souvent important entre anciens et nouveaux baux.") },

  { id: "m2-complements", theme: "marche", niveau: 2, type: "qcm", notion: "offre-demande",
    titre: "Forfaits de ski et location de skis", competence: "Raisonner sur deux marchés liés.",
    enonce: P("Le prix des forfaits de ski augmente fortement dans les grandes stations suisses. Quel effet peut-on attendre sur le marché de la location de skis dans ces stations ?"),
    options: ["La demande de location de skis augmente, car les skieurs économisent ailleurs.", "La demande de location diminue : sa courbe se déplace vers la gauche.", "L’offre de location de skis diminue.", "Aucun effet : ce sont deux marchés différents."], c: 1, pourquoi: ["Le forfait et la location de skis vont ensemble : si l’un devient plus cher, on skie moins et on loue moins de skis.", null, "Les loueurs ne changent pas leurs coûts : c’est la demande des skieurs qui baisse, pas l’offre de location.", "Les deux marchés sont liés, car on consomme les deux biens ensemble : ce sont des compléments."],
    explication: P("Le forfait et la location de skis sont des <b>biens complémentaires</b> : on les consomme ensemble. Si le forfait devient plus cher, certains skieurs viennent moins souvent ; à chaque prix, on loue moins de skis. La <b>courbe de demande</b> de location se déplace vers la gauche, ce qui tend à faire baisser son prix et la quantité louée.") },

  { id: "m2-nash", theme: "marche", niveau: 2, type: "qcm", notion: "equilibre-nash",
    titre: "La guerre des prix", competence: "Trouver un équilibre de Nash dans une matrice de gains.",
    enonce: P("Deux compagnies de taxis d’une petite ville choisissent chacune un tarif élevé ou un tarif bas. Le tableau indique leur bénéfice quotidien en francs (compagnie A ; compagnie B) :") +
      `<table><thead><tr><th></th><th>B : tarif élevé</th><th>B : tarif bas</th></tr></thead><tbody><tr><th>A : tarif élevé</th><td>800 ; 800</td><td>200 ; 1000</td></tr><tr><th>A : tarif bas</th><td>1000 ; 200</td><td>400 ; 400</td></tr></tbody></table>` +
      P("Quel est l’équilibre de Nash de ce jeu ?"),
    options: ["Les deux gardent un tarif élevé, car c’est l’issue qui leur rapporte le plus.", "Les deux baissent leur tarif, quoi que fasse l’autre.", "L’une garde un tarif élevé et l’autre le baisse.", "Il n’y a pas d’équilibre, car chacune veut gagner plus que l’autre."], c: 1, pourquoi: ["Cette issue rapporte le plus aux deux, mais elle n’est pas stable : chacune gagnerait 1000 au lieu de 800 en baissant seule son tarif.", null, "Celle qui garde un tarif élevé ne gagne que 200 ; elle aurait intérêt à baisser le sien pour gagner 400. Ce n’est donc pas un équilibre.", "Il existe bien un équilibre : (tarif bas, tarif bas), où aucune des deux ne gagne à changer seule."],
    explication: P("Cherchons la meilleure réponse de A. Si B garde un tarif élevé, A gagne 1000 en baissant au lieu de 800. Si B baisse, A gagne 400 en baissant au lieu de 200. Baisser est toujours préférable : c’est une <b>stratégie dominante</b>. Le jeu est symétrique, c’est donc vrai aussi pour B.", "L’<b>équilibre de Nash</b> est (tarif bas, tarif bas), avec 400 francs chacune, alors qu’elles gagneraient 800 en gardant toutes deux un tarif élevé. C’est un <b>dilemme du prisonnier</b> : il existe une issue meilleure pour les deux, mais elle n’est pas stable.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "m3-perte-seche", theme: "marche", niveau: 3, type: "calcul", notion: "surplus",
    titre: "La perte sèche d’une taxe", competence: "Calculer le nouvel équilibre et la perte sèche après une taxe.",
    gen: () => { const [b, d, kk] = pick([[2, 2, 1], [4, 4, 2], [3, 6, 2], [6, 3, 2], [2, 6, 1.5], [6, 2, 1.5]]); const t = pick([2, 4]); const Ps = rnd(6, 14), Qs = rnd(60, 140); return { a: Qs + b * Ps, b, c: Qs - d * Ps, d, t, Ps, Qs, dQ: t * kk }; },
    enonce: (p) => P(`Sur un marché, <b>Q<sub>d</sub> = ${lin(p.a, p.b)}</b> et <b>Q<sub>o</sub> = ${linp(p.c, p.d)}</b>, où P est le prix en francs et Q la quantité en unités.`, `L’État instaure une taxe de <b>${p.t} francs par unité</b>, payée par les vendeurs : ils reçoivent désormais P − ${p.t}.`, "Calculez l’équilibre avant la taxe, puis après la taxe. Donnez la nouvelle quantité échangée, la recette fiscale de l’État et la perte sèche (perte de surplus total non compensée par la recette fiscale). Arrondissez à deux décimales si nécessaire."),
    champs: [{ label: "Nouvelle quantité", unite: "unités", tol: 0.05 }, { label: "Recette fiscale", unite: "fr.", tol: 0.1 }, { label: "Perte sèche", unite: "fr.", tol: 0.05 }],
    reponses: (p) => [X.arr(p.Qs - p.dQ, 2), X.arr(p.t * (p.Qs - p.dQ), 2), X.arr(0.5 * p.t * p.dQ, 2)],
    indice: "Après la taxe, les acheteurs et les vendeurs n’ont plus le même prix. Exprimez l’offre en fonction du prix payé par les acheteurs, puis égalisez-la avec la demande. La perte sèche est un triangle dont la hauteur est l’écart entre les deux prix.",
    correction: (p) => { const P0 = p.Ps, P2 = (p.a - p.c + p.d * p.t) / (p.b + p.d); const Q2 = p.a - p.b * P2; return P(`Avant la taxe : ${lin(p.a, p.b)} = ${linp(p.c, p.d)}, soit ${p.b + p.d}P = ${p.a - p.c}, donc P = ${P0} francs et Q = ${p.a} − ${p.b} × ${P0} = ${p.Qs} unités.`, `Avec la taxe, l’offre devient Q<sub>o</sub> = ${fmt(p.c)} + ${p.d}(P − ${p.t}). Équilibre : ${lin(p.a, p.b)} = ${fmt(p.c)} + ${p.d}P − ${p.d * p.t}, soit ${p.b + p.d}P = ${p.a - p.c + p.d * p.t}, donc P = ${fmt(P2)} francs payés par les acheteurs (les vendeurs reçoivent ${fmt(P2 - p.t)} francs).`, `Nouvelle quantité : Q = ${p.a} − ${p.b} × ${fmt(P2)} = <b>${fmt(Q2)} unités</b>, soit ${fmt(p.dQ)} de moins qu’avant.`, `Recette fiscale = ${p.t} × ${fmt(Q2)} = <b>${fmt(p.t * Q2)} francs</b>.`, `Perte sèche = ½ × ${p.t} × ${fmt(p.dQ)} = <b>${fmt(0.5 * p.t * p.dQ)} francs</b>.`, "Ce sont les échanges qui auraient profité aux deux parties et qui n’ont plus lieu à cause de la taxe."); } },

  { id: "m3-incidence", theme: "marche", niveau: 3, type: "calcul", notion: "surplus",
    titre: "Qui paie vraiment la taxe ?", competence: "Calculer l’incidence fiscale à partir des élasticités.",
    gen: () => { const [ed, eo] = pick([[0.5, 1.5], [1, 3], [1.5, 0.5], [2, 1], [3, 1], [1, 1], [2, 2], [0.5, 2]]); const P0 = pick([20, 40, 50, 80]); const pc = pick([5, 10]); return { ed, eo, P0, pc, t: P0 * pc / 100 }; },
    enonce: (p) => P(`Sur un marché, le prix d’équilibre est de <b>${p.P0} francs</b>. Au voisinage de l’équilibre, l’élasticité-prix de la demande vaut <b>−${fmt(p.ed)}</b> et celle de l’offre <b>+${fmt(p.eo)}</b>.`, `On instaure une taxe de <b>${fmt(p.t)} franc${p.t >= 2 ? "s" : ""} par unité</b> (${p.pc} % du prix), payée par les vendeurs. La taxe est assez faible pour que les élasticités restent constantes.`, "Calculez la part de la taxe supportée par les acheteurs (en %, à une décimale), de combien augmente le prix qu’ils paient (à deux décimales), et la variation de la quantité échangée (en %, à une décimale, avec un signe moins pour une baisse). Dites aussi qui supporte la plus grande part de la taxe."),
    champs: [{ label: "Part des acheteurs", unite: "%", tol: 0.1 }, { label: "Hausse du prix payé", unite: "fr.", tol: 0.011 }, { label: "Variation de la quantité", unite: "%", tol: 0.1 }, { label: "Qui supporte la plus grande part ?", choix: ["les acheteurs", "les vendeurs", "les deux à parts égales"] }],
    reponses: (p) => { const s = p.eo / (p.eo + p.ed); return [X.arr(100 * s, 1), X.arr(p.t * s, 2), X.arr(-(p.eo * p.ed / (p.eo + p.ed)) * (p.t / p.P0) * 100, 1), s > 0.5 ? 0 : s < 0.5 ? 1 : 2]; },
    indice: "Après la taxe, le prix payé par les acheteurs monte et le prix reçu par les vendeurs baisse, et la somme de ces deux variations est égale à la taxe. La quantité échangée est la même vue des deux côtés : exprimez sa variation en % avec l’élasticité de la demande, puis avec celle de l’offre, et égalisez.",
    correction: (p) => { const s = p.eo / (p.eo + p.ed), h = p.t * s, vq = -(p.eo * p.ed / (p.eo + p.ed)) * (p.t / p.P0) * 100; return P(`Notons h la hausse du prix payé par les acheteurs. Les vendeurs reçoivent alors ${fmt(p.t)} − h de moins. Côté demande, la quantité varie de −${fmt(p.ed)} × h ÷ ${p.P0}. Côté offre, elle varie de ${fmt(p.eo)} × (h − ${fmt(p.t)}) ÷ ${p.P0}. Ces deux variations sont égales.`, `On obtient −${fmt(p.ed)} × h = ${fmt(p.eo)} × (h − ${fmt(p.t)}), donc h = ${fmt(p.t)} × ${fmt(p.eo)} ÷ (${fmt(p.eo)} + ${fmt(p.ed)}) ${Math.abs(h * 100 - Math.round(h * 100)) < 1e-6 ? "=" : "≈"} <b>${fmt(h, 2)} franc${h >= 2 ? "s" : ""}</b>.`, `Part des acheteurs : h ÷ taxe = εo ÷ (εo + |εd|) = ${fmt(p.eo)} ÷ ${fmt(p.eo + p.ed)} = <b>${fmt(100 * s, 1)} %</b>. Les vendeurs supportent le reste, ${fmt(p.t - h, 2)} franc${p.t - h >= 2 ? "s" : ""}.`, `Variation de la quantité : −${fmt(p.ed)} × ${fmt(h, 2)} ÷ ${p.P0} ≈ <b>${fmt(vq, 1)} %</b>.`, s > 0.5 ? "Le côté le moins capable de s’adapter supporte la plus grande part de la taxe. Ici, l’offre est plus élastique que la demande : les vendeurs peuvent réduire leur production, les acheteurs peuvent difficilement renoncer, et ce sont surtout les <b>acheteurs</b> qui paient." : s < 0.5 ? "Le côté le moins capable de s’adapter supporte la plus grande part de la taxe. Ici, la demande est plus élastique que l’offre : les acheteurs peuvent se détourner, et ce sont surtout les <b>vendeurs</b> qui paient." : "Les deux élasticités sont égales : la taxe est partagée à parts égales entre <b>acheteurs et vendeurs</b>.", "Le résultat ne dépend pas de celui qui verse la taxe à l’État, mais de la capacité de chaque côté du marché à réagir au prix."); } },

  { id: "m3-monopole", theme: "marche", niveau: 3, type: "calcul", notion: "concurrence-imparfaite",
    titre: "Le prix d’un monopole", competence: "Déterminer la quantité et le prix qui maximisent le profit d’un monopole.",
    gen: () => { const b = pick([1, 2]); const Qm = rnd(5, 20); const c = rnd(4, 20); return { b, Qm, c, a: c + 2 * b * Qm }; },
    enonce: (p) => P(`Une entreprise est seule à fabriquer un médicament breveté. La demande est <b>P = ${p.a} − ${p.b === 1 ? "" : p.b}Q</b> (P en francs, Q en milliers de boîtes), et chaque boîte lui coûte <b>${p.c} francs</b> à produire (coût marginal constant).`, "Écrivez la recette totale, déduisez-en la recette marginale, puis calculez la quantité et le prix qui maximisent son profit. Calculez ensuite son profit (en milliers de francs) et la perte sèche par rapport à la concurrence parfaite (en milliers de francs, à une décimale si nécessaire)."),
    champs: [{ label: "Quantité", unite: "milliers", tol: 0.05 }, { label: "Prix", unite: "fr.", tol: 0.05 }, { label: "Profit", unite: "milliers de fr.", tol: 0.05 }, { label: "Perte sèche", unite: "milliers de fr.", tol: 0.05 }],
    reponses: (p) => [p.Qm, p.a - p.b * p.Qm, (p.a - p.b * p.Qm - p.c) * p.Qm, X.arr(0.5 * (p.a - p.b * p.Qm - p.c) * p.Qm, 2)],
    indice: "Le profit est maximal quand la recette marginale est égale au coût marginal. La recette marginale est la dérivée de la recette totale. La perte sèche est le triangle compris entre la demande et le coût marginal, entre la quantité du monopole et celle de la concurrence parfaite.",
    correction: (p) => { const Pm = p.a - p.b * p.Qm, marge = Pm - p.c; return P(`Recette totale : R = P × Q = ${p.a}Q − ${p.b === 1 ? "" : p.b}Q². Recette marginale : Rm = dR/dQ = ${p.a} − ${2 * p.b}Q.`, `Condition de profit maximal : recette marginale = coût marginal, soit ${p.a} − ${2 * p.b}Q = ${p.c}. Donc Q = (${p.a} − ${p.c}) ÷ ${2 * p.b} = <b>${p.Qm} milliers de boîtes</b>.`, `Prix : on le lit sur la demande, P = ${p.a} − ${p.b === 1 ? "" : p.b + " × "}${p.Qm} = <b>${Pm} francs</b>.`, `Profit = (P − coût marginal) × Q = (${Pm} − ${p.c}) × ${p.Qm} = <b>${fmt(marge * p.Qm)} milliers de francs</b>.`, `En concurrence parfaite, le prix serait égal au coût marginal : ${p.a} − ${p.b === 1 ? "" : p.b}Q = ${p.c}, soit Q = ${2 * p.Qm} milliers. Le monopole produit <b>deux fois moins</b>. La perte sèche est le triangle de base ${p.Qm} (${2 * p.Qm} − ${p.Qm}) et de hauteur ${marge} (${Pm} − ${p.c}) : ½ × ${p.Qm} × ${marge} = <b>${fmt(0.5 * marge * p.Qm, 2)} milliers de francs</b>.`, "Ce sont des échanges que des acheteurs auraient payés plus que leur coût de production et qui n’ont pas lieu. C’est la raison d’être des autorités de la concurrence, et la contrepartie que la société accepte pour récompenser l’innovation par un brevet."); } },

  { id: "m3-croisee", theme: "marche", niveau: 3, type: "qcm", notion: "elasticite",
    titre: "Élasticité croisée", competence: "Interpréter le signe d’une élasticité croisée.",
    enonce: P("Une ville augmente le prix des billets de bus de 10 %. Le nombre de locations de vélos en libre-service augmente de 6 %, et les ventes de cartes à prépaiement pour le bus baissent de 8 %.", "Que peut-on en conclure ?"),
    options: ["Les vélos en libre-service sont des compléments du bus ; les cartes à prépaiement, des substituts.", "Vélos et bus sont des substituts (+0,6) ; cartes à prépaiement et bus sont des compléments (−0,8).", "Les deux élasticités sont négatives, car le prix du bus a augmenté.", "On ne peut rien conclure sans connaître le prix des vélos."], c: 1, pourquoi: ["C’est l’inverse : on loue plus de vélos quand le bus est plus cher, ce sont donc des substituts ; les cartes à prépaiement vont avec le bus.", null, "Le signe dépend de la réaction de chaque bien : les vélos augmentent (+0,6), les cartes à prépaiement baissent (−0,8).", "L’élasticité croisée se calcule à partir du prix du bus et des quantités de l’autre bien : le prix des vélos n’est pas nécessaire."],
    explication: P("L’élasticité croisée mesure la réaction de la demande d’un bien B à une variation du prix d’un bien A : variation en % de la quantité de B ÷ variation en % du prix de A.", "Vélos : +6 % ÷ +10 % = <b>+0,6</b>. Positive : quand le bus devient plus cher, on loue plus de vélos, ce sont des <b>substituts</b>.", "Cartes à prépaiement : −8 % ÷ +10 % = <b>−0,8</b>. Négative : elles sont utilisées <i>avec</i> le bus, ce sont des <b>compléments</b>.") },

  { id: "m3-penurie", theme: "marche", niveau: 3, type: "calcul", notion: "surplus",
    titre: "Mesurer une pénurie due à un plafonnement", competence: "Calculer l’écart entre quantité demandée et offerte à un prix plafond.",
    gen: () => { const b = rnd(2, 5), d = rnd(2, 5), Ps = rnd(18, 30), Qs = rnd(200, 400), gap = rnd(2, 6); return { a: Qs + b * Ps, b, c: Qs - d * Ps, d, Ps, Qs, Pc: Ps - gap }; },
    enonce: (p) => P(`Sur le marché des logements d’une ville (loyers en centaines de francs par mois, quantités en logements), <b>Q<sub>d</sub> = ${lin(p.a, p.b)}</b> et <b>Q<sub>o</sub> = ${linp(p.c, p.d)}</b>. L’équilibre est à P = ${p.Ps}.`, `La commune plafonne le loyer à <b>P = ${p.Pc}</b>. Combien de logements manque-t-il à ce prix ? Calculez aussi la perte sèche du plafonnement, c’est-à-dire la perte de surplus total due aux logements qui ne sont plus loués (en centaines de francs par mois, arrondie à l’unité). On suppose que les logements loués vont aux ménages qui les valorisent le plus.`),
    figp: () => OEC.exo.marche({ plafond: true, caption: "Au prix plafond, la quantité demandée dépasse la quantité offerte." }),
    champs: [{ label: "Pénurie", unite: "logements", tol: 0.5 }, { label: "Perte sèche", unite: "centaines de fr. par mois", tol: 0.5 }],
    reponses: (p) => [(p.a - p.b * p.Pc) - (p.c + p.d * p.Pc), X.arr(0.5 * p.d * (p.Ps - p.Pc) * ((p.a - (p.c + p.d * p.Pc)) / p.b - p.Pc), 0)],
    indice: "Seuls les logements offerts au prix plafond sont loués. Pour cette quantité, cherchez sur la courbe de demande le loyer que les locataires accepteraient de payer, puis calculez le triangle entre ce loyer, le prix plafond et la quantité d’équilibre.",
    correction: (p) => { const qd = p.a - p.b * p.Pc, qo = p.c + p.d * p.Pc, pd = (p.a - qo) / p.b, ps = 0.5 * (p.Qs - qo) * (pd - p.Pc), ex = Math.abs(pd * 100 - Math.round(pd * 100)) < 1e-6, eg = ex ? "=" : "≈", eg2 = ex && Math.abs(ps - Math.round(ps)) < 1e-9 ? "=" : "≈"; return P(`Au prix plafond P = ${p.Pc} : quantité demandée = ${p.a} − ${p.b} × ${p.Pc} = ${qd} logements.`, `Quantité offerte = ${p.c} + ${p.d} × ${p.Pc} = ${qo} logements.`, `Pénurie = ${qd} − ${qo} = <b>${qd - qo} logements</b>.`, `Seuls ${qo} logements sont loués. Sur la demande, le loyer que les locataires accepteraient de payer pour le dernier logement loué est P = (${p.a} − ${qo}) ÷ ${p.b} ${eg} ${fmt(pd, 2)}.`, `La quantité d’équilibre est ${p.Qs}. La perte sèche est le triangle de base ${p.Qs} − ${qo} = ${p.Qs - qo} logements et de hauteur ${fmt(pd, 2)} − ${p.Pc} ${eg} ${fmt(pd - p.Pc, 2)} : ½ × ${p.Qs - qo} × ${fmt(pd - p.Pc, 2)} ${eg2} <b>${fmt(ps, 0)} centaines de francs par mois</b>.`, "Ces logements auraient pu être loués à un prix que les locataires acceptaient de payer et qui couvrait le coût des propriétaires. Ils ne le sont plus. À long terme, si les propriétaires construisent et entretiennent moins, l’offre peut encore diminuer et la perte s’alourdir."); } },

  { id: "m3-vf-monopsone", theme: "marche", niveau: 3, type: "vf", notion: "concurrence-imparfaite",
    titre: "Monopole, oligopole et discrimination par les prix", competence: "Prévoir le comportement d’entreprises qui ont un pouvoir de marché.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Face à la même demande linéaire et au même coût marginal constant, un monopole produit moins qu’un ensemble d’entreprises en concurrence parfaite et vend plus cher.", true, "Le monopole sait que, pour vendre une unité de plus, il doit baisser le prix sur toutes les unités. Sa recette marginale est inférieure au prix, il s’arrête là où elle égale le coût marginal : avec une demande linéaire, il produit la moitié de la quantité de concurrence parfaite."],
      ["Un monopole à qui l’on impose une taxe forfaitaire, la même quelle que soit la quantité produite, réduit sa production pour la payer.", false, "Une taxe forfaitaire s’ajoute aux coûts fixes. Elle diminue le profit, mais ne change ni la recette marginale ni le coût marginal. La quantité qui maximise le profit reste la même, et le prix aussi. Une taxe par unité vendue aurait au contraire fait monter le coût marginal."],
      ["Deux cimenteries qui se sont entendues pour limiter leur production tiennent leur accord sans surveillance : aucune n’a intérêt à produire plus que la quantité convenue.", false, "Si l’autre respecte l’accord, produire un peu plus que sa part augmente le profit, car le prix reste élevé. Les deux entreprises sont donc tentées de tricher. Sans contrôle ni sanction, l’entente se défait, c’est le dilemme du prisonnier, et la production se rapproche de l’équilibre de Cournot."],
      ["Une entreprise qui sépare deux marchés fixe un prix plus élevé sur celui où la demande est la moins élastique.", true, "La règle de l’élasticité inverse donne un taux de marge égal à 1 ÷ |ε|. Là où les clients réagissent peu au prix, la marge est plus grande et le prix plus élevé. Cela suppose que les clients du marché bon marché ne puissent pas revendre aux autres."]
    ] },

  { id: "m3-plafonner-loyers", theme: "marche", niveau: 3, type: "redaction", notion: "surplus",
    titre: "Faut-il plafonner les loyers ?", competence: "Construire une argumentation équilibrée et conclure.",
    enonce: P("Face à la hausse des loyers, plusieurs villes européennes, comme Berlin entre 2020 et 2021, ont plafonné ou gelé les loyers. En Suisse, le droit du bail permet déjà de contester un loyer jugé abusif, et certains proposent d’aller plus loin.", "<b>Consigne :</b> faut-il plafonner les loyers ? Présentez les arguments en faveur et les arguments contre, en utilisant au moins une notion d’économie (offre et demande, prix plafond, pénurie, surplus, incitations), puis terminez par une prise de position justifiée. Distinguez les effets à court terme et à long terme. Rattachez chaque position à une école ou à un auteur, et dites sur quelle hypothèse ils s’opposent. Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse présente au moins deux arguments en faveur du plafonnement (protection des locataires, justice sociale, mixité, logement comme besoin essentiel, pouvoir de négociation des bailleurs…).", "Elle présente au moins deux arguments contre (pénurie, baisse de l’offre et de l’entretien, marché noir ou sélection des locataires, logements retirés du marché…).", "Elle nomme au moins une notion d’économie et l’explique en une phrase (par exemple, un prix plafond inférieur à l’équilibre crée une pénurie).", "Elle distingue le court terme et le long terme, ou nuance selon la forme du plafonnement.", "La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Les écoles en présence.</b> L’analyse concurrentielle, défendue par Milton Friedman et George Stigler dès 1946 dans « Roofs or Ceilings? », suppose que les bailleurs sont preneurs de prix et que les locataires peuvent changer de logement sans coût : un prix plafond inférieur à l’équilibre ne peut alors que créer une pénurie. Les travaux qui insistent sur les frictions du marché du logement, comme l’article de Richard Arnott (1995) sur la réévaluation du contrôle des loyers, partent d’une hypothèse inverse : déménager coûte cher, l’information est imparfaite, et les bailleurs disposent d’un pouvoir de marché sur les locataires en place. Dans ce cas, un encadrement peut limiter des hausses qui ne reflètent pas la rareté, sans que la pénurie soit aussi forte. Les deux lectures s’opposent donc sur l’hypothèse de concurrence parfaite, et l’étude de Diamond, McQuade et Qian (2019) sur San Francisco illustre ce débat : les locataires protégés sont restés plus longtemps dans leur logement, mais des propriétaires ont retiré des logements du marché locatif, ce qui a fait monter les loyers pour les autres.", "<b>Pour :</b> le logement est un besoin essentiel, et quand l’offre réagit lentement, les propriétaires peuvent imposer de fortes hausses aux locataires en place, qui ont peu de choix. Un plafonnement protège les ménages modestes, évite qu’ils soient chassés de leur quartier et préserve la mixité sociale.", "<b>Contre :</b> un prix plafond inférieur à l’équilibre crée une <b>pénurie</b> : la quantité demandée dépasse l’offre. Les logements disponibles se raréfient, les bailleurs choisissent les locataires les plus sûrs, et un marché parallèle peut apparaître. À long terme, si la rentabilité baisse, on construit et on entretient moins. L’expérience de Berlin, où le plafonnement a été annulé par la justice en 2021, a montré une forte baisse du nombre de logements proposés à la location.", "<b>Conclusion :</b> un plafonnement peut protéger les locataires en place à court terme, mais il ne crée aucun logement. Il est plus efficace de l’associer, ou de le préférer, à des mesures qui augmentent l’offre (densification, logements d’utilité publique) et à des aides ciblées pour les ménages modestes.", "Attention aux comparaisons : les études les plus citées, à San Francisco ou à Berlin, portent sur des gels ou des plafonds stricts. Le droit suisse du bail fonctionne autrement : une hausse de loyer doit être justifiée, notamment par le taux hypothécaire de référence, le renchérissement ou des travaux, et un loyer jugé abusif peut être contesté. Les effets d’un encadrement dépendent donc beaucoup de sa forme.") },

  { id: "m3-degriffes", theme: "marche", niveau: 3, type: "qcm", notion: "concurrence-imparfaite",
    titre: "Les billets dégriffés", competence: "Expliquer la logique économique d’une offre tarifaire.",
    enonce: P("Les CFF vendent des billets « dégriffés », moins chers, pour certains trains peu fréquentés, à réserver à l’avance et valables seulement pour ce train. Le prix normal reste inchangé pour les autres voyageurs.", "Quelle est la logique économique principale de cette offre ?"),
    options: ["Faire payer davantage les voyageurs pressés, afin de compenser les pertes des trains peu remplis.", "Attirer les clients sensibles au prix sans baisser le tarif de ceux qui paieraient plus.", "Respecter une obligation légale de proposer des billets bon marché sur certaines lignes.", "Réduire la demande aux heures de pointe en augmentant le prix du billet normal."], c: 1, pourquoi: ["Le prix normal ne change pas : les voyageurs pressés ne paient pas plus qu’avant.", null, "Aucune loi n’oblige à vendre ces billets : c’est un choix commercial pour remplir des trains peu fréquentés.", "Le prix normal reste inchangé, et les billets dégriffés visent les trains peu remplis, pas les heures de pointe."],
    explication: P("C’est une forme de <b>discrimination par les prix</b> : vendre le même service à des prix différents selon la disposition à payer. Les voyageurs flexibles et sensibles au prix (étudiants, retraités, loisirs) prennent un billet dégriffé sur un train peu rempli ; les voyageurs qui ont besoin de flexibilité paient le plein tarif.", "Les conditions (réservation, train imposé) empêchent la plupart des voyageurs pressés de profiter du rabais. Comme le coût d’un passager supplémentaire dans un train peu rempli est très faible, l’entreprise gagne des recettes, et des voyageurs qui ne seraient pas partis peuvent voyager.") },
  { id: "m3-clemence", theme: "marche", niveau: 3, type: "qcm", notion: "equilibre-nash",
    titre: "Faire éclater un cartel", competence: "Analyser une règle de droit avec la théorie des jeux.",
    enonce: P("Trois entreprises de construction se sont entendues pendant des années sur les prix des marchés publics de leur région. La loi sur les cartels prévoit que la première entreprise qui dénonce un cartel auquel elle participe peut échapper entièrement à l’amende ; les suivantes peuvent obtenir une réduction.", "Pourquoi ce programme de clémence rend-il les cartels plus fragiles ?"),
    options: ["Parce qu’il réduit les amendes de toutes les entreprises, qui n’ont plus peur d’être sanctionnées.", "Parce qu’il crée un dilemme du prisonnier : chacun craint d’être dénoncé et a intérêt à parler le premier.", "Parce qu’il oblige l’État à fixer lui-même les prix des marchés publics.", "Parce qu’il interdit aux entreprises concurrentes de se rencontrer pour discuter des prix."], c: 1, pourquoi: ["La clémence ne profite qu’à celui qui dénonce le premier : les autres restent exposés à l’amende, ce qui renforce la peur d’être dénoncé.", null, "L’État ne fixe pas les prix : il sanctionne les ententes et laisse la concurrence fixer les prix des appels d’offres.", "Le programme n’interdit rien de nouveau : il rend la trahison avantageuse, ce qui détruit la confiance entre les membres du cartel."],
    explication: P("Sans programme de clémence, se taire est la meilleure réponse de chacun tant que les autres se taisent : le cartel est un <b>équilibre</b> stable, entretenu par la répétition des appels d’offres.", "Avec la clémence, le calcul change. Celui qui parle le premier efface son amende, celui qui se tait risque d’être dénoncé et de payer plein tarif. Dénoncer n’est pas toujours le meilleur choix, car on renonce aux profits du cartel, mais se taire devient risqué dès qu’on doute des autres. Cette méfiance suffit souvent à faire éclater l’entente.", "En Suisse, la Commission de la concurrence (Comco) applique ce mécanisme depuis la révision de la loi sur les cartels entrée en vigueur en 2004. L’amende peut atteindre 10 % du chiffre d’affaires réalisé en Suisse pendant les trois derniers exercices, ce qui donne tout son poids à l’immunité offerte au premier qui parle. L’Union européenne et les États-Unis ont des programmes comparables.") },
  { id: "m1-fait-valeur", theme: "marche", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Constat ou jugement de valeur ?", competence: "Distinguer un constat, que l’on peut vérifier, d’un jugement de valeur, qui dit ce qui devrait être.",
    enonce: P("Pour chaque affirmation, dites s’il s’agit d’un <b>constat</b>, que l’on peut vérifier avec des données, même s’il se révèle faux, ou d’un <b>jugement de valeur</b>, qui dit ce qui devrait être."),
    affirmations: [
      ["Il est injuste que les loyers soient si élevés à Genève pour les familles modestes.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : « injuste » est une appréciation."],
      ["Quand le prix d’un bien augmente, la quantité demandée diminue en général.", true, "On peut le vérifier avec des données, et les observations le confirment dans la grande majorité des marchés."],
      ["Après le plafonnement des loyers à Berlin en 2020, le nombre d’annonces de location a baissé.", true, "On peut le vérifier avec des données : des études l’ont mesuré sur les annonces publiées."],
      ["L’État devrait garantir un logement abordable à chacun, quel que soit son revenu.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : « devrait » signale un choix politique."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "m1-seuil", theme: "marche", niveau: 1, type: "calcul",
    titre: "Le seuil de rentabilité d’un tea-room", competence: "Calculer une marge par unité et un seuil de rentabilité.",
    gen: () => { const m = rnd(10, 15), n = rnd(10, 18) * 100, cv = rnd(7, 11); return { m, n, cv, prix: cv + m, cf: m * n }; },
    enonce: (p) => P(`Un tea-room supporte <b>${fmt(p.cf)} francs</b> de coûts fixes par mois (loyer, salaires, assurances). Un menu est vendu <b>${p.prix} francs</b> et coûte <b>${p.cv} francs</b> en marchandises.`, "Calculez la marge réalisée sur chaque menu, puis le nombre de menus à vendre par mois pour couvrir tous les coûts."),
    champs: [{ label: "Marge par menu", unite: "fr.", tol: 0.01 }, { label: "Seuil de rentabilité", unite: "menus", tol: 0.5 }],
    reponses: (p) => [p.m, p.n],
    indice: "La marge par menu est le prix de vente moins le coût en marchandises. Le seuil est atteint quand la somme des marges couvre les coûts fixes.",
    correction: (p) => P(`Marge par menu = ${p.prix} − ${p.cv} = <b>${p.m} francs</b>.`, `Seuil de rentabilité = coûts fixes ÷ marge par menu = ${fmt(p.cf)} ÷ ${p.m} = <b>${fmt(p.n)} menus</b> par mois.`, `En dessous de ${fmt(p.n)} menus, le tea-room perd de l’argent. Au-dessus, chaque menu supplémentaire ajoute ${p.m} francs au bénéfice.`) },

  { id: "m1-graph-excedent", theme: "marche", niveau: 1, type: "graphique", notion: "offre-demande",
    titre: "Lire un excédent sur un graphique", competence: "Lire des quantités offertes et demandées sur un graphique chiffré.",
    enonce: P("Le graphique représente le marché du miel d’une région, en pots par semaine. Les apiculteurs décident de vendre le pot <b>8 francs</b>.", "Que montre le graphique à ce prix ?"),
    fig: () => X.graphe({ xmax: 100, ymax: 11.5, ylab: "Prix (fr.)", xlab: "Pots par semaine", aria: "Offre et demande de miel, avec un prix de 8 francs supérieur au prix d’équilibre de 6 francs",
      gx: [[20, "20"], [40, "40"], [60, "60"], [80, "80"]], gy: [[2, "2"], [4, "4"], [6, "6"], [8, "8"], [10, "10"]], reperes: [[40, 6], [20, 8], [60, 8]],
      lignes: [{ pts: [[0, 10], [92, 0.8]], col: "d", lab: "D", at: [94, 0.8], dy: -2 }, { pts: [[0, 2], [88, 10.8]], col: "o", lab: "O", at: [90, 10.8], dy: 6 }, { pts: [[0, 8], [72, 8]], col: "r", dash: true, lab: "prix de 8 fr.", at: [73, 8], dy: 6 }],
      points: [{ x: 40, y: 6, lab: "E", dx: 16, dy: 6 }, { x: 20, y: 8, col: "d" }, { x: 60, y: 8, col: "o" }],
      caption: "D est la demande, O l’offre et E l’équilibre du marché." }),
    options: ["Il y a un excédent de 40 pots, et le prix tend à baisser vers 6 francs.", "Il y a une pénurie de 40 pots, et le prix tend à monter au-dessus de 8 francs.", "Le marché est à l’équilibre, puisque 60 pots sont offerts à ce prix.", "Il y a un excédent de 20 pots, l’écart entre 60 pots et la quantité d’équilibre."], c: 0,
    pourquoi: [null, "L’écart est bien de 40 pots, mais dans l’autre sens. À 8 francs, les apiculteurs offrent 60 pots et les clients n’en demandent que 20. Il reste des invendus, ce qui pousse le prix à la baisse.", "L’équilibre exige que la quantité offerte soit égale à la quantité demandée. À 8 francs, 60 pots sont offerts mais 20 seulement sont demandés.", "L’excédent compare l’offre et la demande au même prix, soit 60 − 20 = 40 pots. La quantité d’équilibre, 40 pots, n’entre pas dans ce calcul."],
    explication: P("À 8 francs, on lit sur la droite de demande <b>20 pots</b> et sur la droite d’offre <b>60 pots</b>. L’excédent vaut 60 − 20 = <b>40 pots</b>.", "Pour écouler leurs invendus, les apiculteurs baissent leur prix. La quantité demandée augmente, la quantité offerte diminue, et le marché revient vers l’équilibre E, à 6 francs et 40 pots.") },

  { id: "m1-couts", theme: "marche", niveau: 1, type: "document",
    titre: "Coûts fixes et coûts variables", competence: "Distinguer les coûts fixes des coûts variables dans un tableau.",
    enonce: P("Un atelier de maroquinerie relève son coût total selon le nombre de sacs fabriqués dans le mois.") +
      `<table><thead><tr><th>Sacs fabriqués</th><th>Coût total (fr.)</th></tr></thead><tbody><tr><td>0</td><td>2 000</td></tr><tr><td>100</td><td>2 600</td></tr><tr><td>200</td><td>3 200</td></tr><tr><td>300</td><td>3 800</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Que valent les coûts fixes mensuels et le coût variable par sac ?"),
    options: ["Coûts fixes de 2 000 francs, coût variable de 6 francs par sac.", "Coûts fixes de 2 600 francs, coût variable de 26 francs par sac.", "Aucun coût fixe, coût variable de 12,67 francs par sac.", "Coûts fixes de 2 000 francs, coût variable de 600 francs par sac."], c: 0,
    pourquoi: [null, "2 600 francs est le coût total de 100 sacs. Il contient déjà 600 francs de coûts variables. Et 26 francs est un coût moyen (2 600 ÷ 100), qui mélange coûts fixes et coûts variables.", "12,67 francs est le coût moyen de 300 sacs (3 800 ÷ 300). Or l’atelier paie 2 000 francs même quand il ne fabrique rien. Ce sont des coûts fixes.", "600 francs est le coût de 100 sacs supplémentaires. Pour un seul sac, il faut diviser par 100, soit 6 francs."],
    explication: P("Les <b>coûts fixes</b> ne dépendent pas de la quantité produite. On les lit sur la ligne « 0 sac », soit <b>2 000 francs</b> (loyer, machines, assurances).", "Les <b>coûts variables</b> augmentent avec la production. Chaque tranche de 100 sacs ajoute 600 francs au coût total, soit 600 ÷ 100 = <b>6 francs par sac</b> (cuir, fil, énergie).", "Cette distinction sert à calculer un seuil de rentabilité et à décider si une commande supplémentaire vaut la peine d’être acceptée.") },

  /* ----- Niveau 2 ----- */
  { id: "m2-levier", theme: "marche", niveau: 2, type: "calcul",
    titre: "Marge de sécurité et levier opérationnel", competence: "Mesurer la sensibilité d’un résultat au volume des ventes.",
    gen: () => { const m = rnd(10, 15), n = rnd(10, 16) * 100, k = pick([1.25, 1.5, 1.6]); return { m, n, q: Math.round(n * k), cf: m * n }; },
    enonce: (p) => P(`Un tea-room supporte <b>${fmt(p.cf)} francs</b> de coûts fixes par mois. Chaque menu vendu laisse une marge de <b>${p.m} francs</b> (prix de vente moins coût variable). Il vend <b>${fmt(p.q)} menus</b> par mois.`, "Calculez son résultat mensuel, sa marge de sécurité (la part des ventes qu’il peut perdre avant de tomber en perte), puis la variation de son résultat si les ventes baissent de 10 %. Arrondissez les pourcentages à une décimale et indiquez un signe moins pour une baisse."),
    champs: [{ label: "Résultat mensuel", unite: "fr.", tol: 0.5 }, { label: "Marge de sécurité", unite: "%", tol: 0.1 }, { label: "Variation du résultat", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.m * (p.q - p.n), Math.round(((p.q - p.n) / p.q) * 1000) / 10, Math.round((-10 * p.q / (p.q - p.n)) * 10) / 10],
    indice: "Cherchez d’abord le seuil de rentabilité (coûts fixes ÷ marge par menu). La marge de sécurité compare les ventes au seuil. Pour la dernière question, recalculez le résultat avec 10 % de menus en moins.",
    correction: (p) => { const res = p.m * (p.q - p.n), q2 = 0.9 * p.q, res2 = p.m * q2 - p.cf; return P(`Marge totale = ${fmt(p.q)} × ${p.m} = ${fmt(p.m * p.q)} francs. Résultat = ${fmt(p.m * p.q)} − ${fmt(p.cf)} = <b>${fmt(res)} francs</b>.`, `Seuil de rentabilité = ${fmt(p.cf)} ÷ ${p.m} = ${fmt(p.n)} menus. Marge de sécurité = (${fmt(p.q)} − ${fmt(p.n)}) ÷ ${fmt(p.q)} = <b>${fmt(((p.q - p.n) / p.q) * 100, 1)} %</b>.`, `Avec 10 % de ventes en moins, soit ${fmt(q2)} menus, le résultat devient ${fmt(p.m * q2)} − ${fmt(p.cf)} = ${fmt(res2)} francs. Variation = (${fmt(res2)} − ${fmt(res)}) ÷ ${fmt(res)} = <b>${fmt((-10 * p.q) / (p.q - p.n), 1)} %</b>.`, `Le résultat réagit ${fmt(p.q / (p.q - p.n), 2)} fois plus fort que les ventes. Ce rapport, marge totale ÷ résultat, est le <b>levier opérationnel</b>. Plus les coûts fixes pèsent lourd, plus il est élevé et plus l’entreprise est exposée à une baisse d’activité.`); } },

  { id: "m2-graph-surplus", theme: "marche", niveau: 2, type: "graphique", notion: "surplus",
    titre: "Lire les surplus sur un graphique", competence: "Repérer et mesurer le surplus des consommateurs et celui des producteurs.",
    enonce: P("Le graphique représente le marché des billets d’un festival. À l’équilibre, 60 billets sont vendus 6 francs. Deux surfaces sont colorées, A et B.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 110, ymax: 13.5, ylab: "Prix (fr.)", xlab: "Billets", aria: "Offre et demande de billets, avec la surface A au-dessus du prix et la surface B en dessous",
      zones: [{ pts: [[0, 12], [60, 6], [0, 6]], col: "d", lab: "A", at: [18, 8] }, { pts: [[0, 6], [60, 6], [0, 3]], col: "o", lab: "B", at: [18, 5] }],
      gx: [[60, "60"]], gy: [[3, "3"], [6, "6"], [12, "12"]], reperes: [[60, 6]],
      lignes: [{ pts: [[0, 12], [100, 2]], col: "d", lab: "D", at: [102, 2], dy: 4 }, { pts: [[0, 3], [100, 8]], col: "o", lab: "O", at: [102, 8], dy: 4 }],
      points: [{ x: 60, y: 6, lab: "E", dx: 4, dy: -12 }],
      caption: "La demande coupe l’axe des prix à 12 francs, l’offre à 3 francs." }),
    options: ["A est le surplus des consommateurs (180 francs), B celui des producteurs (90 francs).", "A est le surplus des producteurs (180 francs), B celui des consommateurs (90 francs).", "A est le surplus des consommateurs (360 francs), B celui des producteurs (180 francs).", "A et B forment ensemble la recette des vendeurs, soit 60 × 6 = 360 francs."], c: 0,
    pourquoi: [null, "Les rôles sont inversés. La surface située sous la demande et au-dessus du prix mesure le gain des acheteurs, qui paient moins que ce qu’ils étaient prêts à payer.", "Les surfaces sont des triangles. Il faut prendre la moitié de base × hauteur, soit ½ × 60 × 6 = 180 et ½ × 60 × 3 = 90.", "La recette est le rectangle prix × quantité, qui s’étend de l’axe horizontal jusqu’au prix de 6 francs. A est au-dessus de ce rectangle, et B n’en couvre qu’une partie."],
    explication: P("Le <b>surplus des consommateurs</b> est la surface comprise entre la demande et le prix payé. A = ½ × 60 × (12 − 6) = <b>180 francs</b>.", "Le <b>surplus des producteurs</b> est la surface comprise entre le prix reçu et l’offre. B = ½ × 60 × (6 − 3) = <b>90 francs</b>.", "Leur somme, 270 francs, mesure le gain total de l’échange. À l’équilibre d’un marché concurrentiel, cette somme est la plus grande possible.") },

  { id: "m2-cout-marginal", theme: "marche", niveau: 2, type: "document", notion: "offre-demande",
    titre: "Combien produire ? Le coût marginal", competence: "Choisir une quantité en comparant le prix et le coût marginal.",
    enonce: P("Un atelier fabrique des vélos-cargos qu’il vend <b>1 500 francs</b> pièce, un prix fixé par le marché. Voici son coût total par semaine.") +
      `<table><thead><tr><th>Vélos produits</th><th>0</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr></thead><tbody><tr><th>Coût total (fr.)</th><td>2 000</td><td>2 900</td><td>3 600</td><td>4 500</td><td>5 800</td><td>7 500</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Combien de vélos l’atelier a-t-il intérêt à produire par semaine ?"),
    options: ["4 vélos, car un cinquième coûterait plus qu’il ne rapporterait.", "5 vélos, car c’est la quantité qui donne la recette la plus élevée.", "2 vélos, car c’est le vélo dont le coût marginal est le plus bas.", "3 vélos, car à partir du quatrième le coût marginal augmente."], c: 0,
    pourquoi: [null, "La recette est la plus élevée avec 5 vélos (7 500 francs), mais le coût total atteint lui aussi 7 500 francs. Le profit est nul.", "Le deuxième vélo est bien le moins cher à produire (700 francs). Mais le troisième et le quatrième coûtent encore moins que le prix de vente. S’arrêter à 2 vélos revient à renoncer à ce gain.", "Un coût marginal qui augmente n’est pas un signal d’arrêt. Tant qu’il reste inférieur au prix, le vélo supplémentaire augmente le profit. Le quatrième coûte 1 300 francs et en rapporte 1 500."],
    explication: P("Le <b>coût marginal</b> est le coût du vélo supplémentaire. Il vaut 900, 700, 900, 1 300 puis 1 700 francs pour les vélos 1 à 5.", "L’atelier produit tant que le coût marginal reste inférieur au prix de 1 500 francs. C’est le cas jusqu’au <b>quatrième vélo</b> (1 300 francs). Le cinquième coûterait 1 700 francs.", "Vérification par le profit. Avec 3 vélos, 4 500 − 4 500 = 0 franc. Avec 4 vélos, 6 000 − 5 800 = <b>200 francs</b>. Avec 5 vélos, 7 500 − 7 500 = 0 franc.", "C’est la règle qui donne sa forme à la courbe d’offre. Quand le prix monte, des unités au coût marginal plus élevé deviennent rentables.") },

  /* ----- Niveau 3 ----- */
  { id: "m3-cournot", theme: "marche", niveau: 3, type: "calcul", notion: "equilibre-nash",
    titre: "Le duopole de Cournot", competence: "Calculer un équilibre de Nash en quantités à partir des fonctions de réaction.",
    gen: () => { const k = rnd(8, 20), c = rnd(2, 8) * 5; return { k, c, a: c + 3 * k }; },
    enonce: (p) => P(`Deux cimenteries se partagent un marché régional. La demande est <b>P = ${p.a} − Q</b>, où Q = q<sub>1</sub> + q<sub>2</sub> est la quantité totale en milliers de tonnes et P le prix en francs par tonne. Chacune produit à un coût marginal constant de <b>${p.c} francs</b>, sans coût fixe.`, "Chaque entreprise choisit sa quantité en tenant celle de sa rivale pour donnée (concurrence à la Cournot). Calculez la quantité produite par chaque entreprise à l’équilibre, le prix du marché et le profit de chacune."),
    champs: [{ label: "Quantité de chaque entreprise", unite: "milliers de t", tol: 0.05 }, { label: "Prix", unite: "fr./t", tol: 0.05 }, { label: "Profit de chaque entreprise", unite: "milliers de fr.", tol: 0.5 }],
    reponses: (p) => [p.k, p.c + p.k, p.k * p.k],
    indice: "Écrivez le profit de l’entreprise 1, (P − c) × q₁, et annulez sa dérivée par rapport à q₁. Vous obtenez sa fonction de réaction. Le jeu est symétrique, donc q₁ = q₂ à l’équilibre.",
    correction: (p) => { const m = p.a - p.c; return P(`Profit de l’entreprise 1 : π<sub>1</sub> = (${p.a} − q<sub>1</sub> − q<sub>2</sub> − ${p.c}) × q<sub>1</sub>. La condition du premier ordre, ${m} − 2q<sub>1</sub> − q<sub>2</sub> = 0, donne la fonction de réaction q<sub>1</sub> = (${m} − q<sub>2</sub>) ÷ 2.`, `Par symétrie, q<sub>1</sub> = q<sub>2</sub> = q, donc 3q = ${m} et q = <b>${p.k} milliers de tonnes</b> pour chaque entreprise.`, `Prix : P = ${p.a} − 2 × ${p.k} = <b>${p.c + p.k} francs</b> par tonne.`, `Profit de chacune : (${p.c + p.k} − ${p.c}) × ${p.k} = <b>${fmt(p.k * p.k)} milliers de francs</b>.`, `Comparaison. Une entente produirait la quantité de monopole, ${fmt(m / 2)} au total, vendue ${fmt(p.c + m / 2)} francs, pour un profit de ${fmt(m * m / 8, 1)} chacune. La concurrence parfaite donnerait ${m} milliers de tonnes à ${p.c} francs. Le duopole de Cournot se situe entre les deux. Chaque membre d’une entente gagnerait à produire un peu plus que sa part, ce qui explique la fragilité des cartels.`); } },

  { id: "m3-lerner", theme: "marche", niveau: 3, type: "calcul", notion: "concurrence-imparfaite",
    titre: "Fixer un prix avec l’élasticité", competence: "Appliquer la règle de l’élasticité inverse à deux marchés séparés.",
    gen: () => { const c = pick([20, 24, 32, 40, 48, 60]), [ea, eb] = pick([[3, 1.5], [5, 2], [3, 2], [5, 1.5], [2, 1.5], [5, 3]]); return { c, ea, eb }; },
    enonce: (p) => P(`Une entreprise vend le même logiciel sur deux marchés qu’elle peut séparer. Son coût marginal est de <b>${p.c} francs</b> par licence. L’élasticité-prix de la demande vaut <b>−${fmt(p.ea)}</b> sur le marché A, où les concurrents sont nombreux, et <b>−${fmt(p.eb)}</b> sur le marché B, où ils sont rares.`, "Le profit est maximal quand (P − Cm) ÷ P = 1 ÷ |ε|. Calculez le prix optimal sur chaque marché, puis le taux de marge sur le prix au marché B (en %, arrondi à une décimale)."),
    champs: [{ label: "Prix sur le marché A", unite: "fr.", tol: 0.01 }, { label: "Prix sur le marché B", unite: "fr.", tol: 0.01 }, { label: "Taux de marge au marché B", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.c * p.ea / (p.ea - 1), p.c * p.eb / (p.eb - 1), Math.round(1000 / p.eb) / 10],
    indice: "Multipliez les deux membres par P, puis regroupez les termes en P du même côté.",
    correction: (p) => P(`La règle (P − Cm) ÷ P = 1 ÷ |ε| se réécrit P = Cm × |ε| ÷ (|ε| − 1).`, `Marché A : P = ${p.c} × ${fmt(p.ea)} ÷ ${fmt(p.ea - 1)} = <b>${fmt(p.c * p.ea / (p.ea - 1))} francs</b>.`, `Marché B : P = ${p.c} × ${fmt(p.eb)} ÷ ${fmt(p.eb - 1)} = <b>${fmt(p.c * p.eb / (p.eb - 1))} francs</b>.`, `Taux de marge au marché B : 1 ÷ ${fmt(p.eb)} = <b>${fmt(100 / p.eb, 1)} %</b> du prix (indice de Lerner).`, "L’entreprise vend plus cher là où la demande réagit le moins. C’est une discrimination par les prix du troisième degré, qui suppose que les clients du marché A ne puissent pas revendre aux clients du marché B.", "La règle n’a de sens que si |ε| est supérieur à 1. Une entreprise qui a un pouvoir de marché ne reste jamais sur la partie inélastique de sa demande, car elle augmenterait à la fois sa recette et son profit en relevant son prix.") },

  { id: "m3-graph-monopole", theme: "marche", niveau: 3, type: "graphique", notion: "concurrence-imparfaite",
    titre: "Monopole, profit et perte sèche", competence: "Lire sur un graphique le choix d’un monopole et ses effets sur les surplus.",
    enonce: P("Le graphique représente un monopole. La demande est D, la recette marginale Rm, et le coût marginal Cm est constant à 20 francs. Trois surfaces sont colorées, A, B et C.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 108, ymax: 110, ylab: "Prix (fr.)", xlab: "Quantité", aria: "Monopole avec demande linéaire, recette marginale et coût marginal constant",
      zones: [{ pts: [[0, 100], [40, 60], [0, 60]], col: "d", lab: "C", at: [11, 72] }, { pts: [[0, 60], [40, 60], [40, 20], [0, 20]], col: "p", lab: "A", at: [20, 40] }, { pts: [[40, 60], [80, 20], [40, 20]], col: "r", lab: "B", at: [52, 34] }],
      gx: [[40, "40"], [50, "50"], [80, "80"]], gy: [[20, "20"], [60, "60"], [100, "100"]], reperes: [[40, 60]],
      lignes: [{ pts: [[0, 100], [100, 0]], col: "d", lab: "D", at: [92, 8], dx: 8, dy: -4 }, { pts: [[0, 100], [50, 0]], col: "o", lab: "Rm", at: [44, 12], dx: -40, dy: 4 }, { pts: [[0, 20], [100, 20]], col: "n", lab: "Cm", at: [100, 20], dx: 6, dy: -8, anc: "end" }],
      points: [{ x: 40, y: 60, lab: "M", dx: 8, dy: -8 }, { x: 40, y: 20, col: "o" }],
      caption: "Demande P = 100 − Q, recette marginale Rm = 100 − 2Q, coût marginal de 20 francs." }),
    options: ["Le monopole produit 40 unités, là où Rm = Cm, et vend 60 francs. La surface B, soit 800 francs, est la perte sèche.", "Le monopole produit 80 unités, là où la demande coupe le coût marginal, et vend 20 francs. Il n’y a pas de perte sèche.", "Le monopole produit 50 unités, là où la recette marginale s’annule, car cette quantité maximise sa recette.", "Le monopole produit 40 unités et vend 60 francs. La surface B est la part de son profit prélevée sur les consommateurs."], c: 0,
    pourquoi: [null, "C’est l’issue de la concurrence parfaite, où le prix est égal au coût marginal. Un monopole gagne davantage en restreignant la quantité pour vendre plus cher.", "Avec 50 unités, la recette est maximale, mais pas le profit. Entre la 41e et la 50e unité, chaque unité rapporte moins que les 20 francs qu’elle coûte à produire.", "Le profit du monopole est la surface A, soit (60 − 20) × 40 = 1 600 francs. La surface B n’est transférée à personne. Elle correspond à des échanges qui n’ont plus lieu."],
    explication: P("Le monopole produit jusqu’à ce que la recette marginale soit égale au coût marginal : 100 − 2Q = 20, donc Q = <b>40</b>. Le prix se lit sur la demande, P = 100 − 40 = <b>60 francs</b>.", "A est son profit, (60 − 20) × 40 = 1 600 francs. C est le surplus qui reste aux consommateurs, ½ × 40 × 40 = 800 francs. B est la <b>perte sèche</b>, ½ × (80 − 40) × (60 − 20) = <b>800 francs</b>. Ce sont les 40 unités que des acheteurs auraient payées plus de 20 francs et qui ne sont pas produites.", "Le poids de cette perte est discuté. Arnold Harberger (1954) l’estimait très faible pour l’industrie américaine. Gordon Tullock et Richard Posner ont répondu que les entreprises dépensent des ressources pour obtenir et défendre leur rente, ce qui alourdit le coût social. Joseph Schumpeter voyait à l’inverse dans le profit de monopole, s’il reste temporaire, la récompense qui finance l’innovation.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
